mapper.select:
SELECT par.point_code, p.point_desc, par.first_time, par.last_time, par.alarm_type, p.unit, par.value, par.closed, se.event_name AS start_event_name, ee.event_name AS end_event_name FROM point_alarm_record par LEFT JOIN point p ON p.point_code = par.point_code LEFT JOIN ( SELECT event_code, event_name FROM basic_event_result_report UNION SELECT event_code, event_name FROM basic_event_result ) se ON se.event_code = p.start_event LEFT JOIN ( SELECT event_code, event_name FROM basic_event_result_report UNION SELECT event_code, event_name FROM basic_event_result ) ee ON ee.event_code = p.end_event WHERE par.first_time >= #{startTime}::timestamp AND par.first_time <= #{endTime}::timestamp AND p.parent_event IN
#{ec}
ORDER BY par.first_time
